I like doing this:

[code]
class LegacyRingCard : LastingCard {
    public override bool IsLimited { get { return true; } }
    public override string[] Keywords { get { return new string[] {"Equipment"}; } }
    public override bool PlayLastingCard() {
        this.Player.PowerCount += 1;
    }
    public override Destroy() {
        this.Player.PowerCount -= 1;
    }
}[/code]
